    "css": " .legacy-content :root{--ink:#0f172a;--muted:#5a5e66;--gold:#c9a84c;--card:#f7f8fa;--border:#e6e8ec;--brand:#0a8a3f} .legacy-content body{font-family:system-ui,-apple-system,sans-serif;max-width:880px;margin:2.5rem auto;padding:0 1.5rem;color:var(--ink);line-height:1.65} .legacy-content h1{margin:0 0 .5rem;font-size:2.3rem;letter-spacing:-.02em} .legacy-content h2{margin-top:2.5rem;margin-bottom:.5rem;border-bottom:1px solid var(--border);padding-bottom:.4rem;font-size:1.4rem} .legacy-content a{color:var(--brand);text-decoration:none} .legacy-content a:hover{text-decoration:underline} .legacy-content .lead{color:var(--muted);font-size:1.1rem;max-width:720px;margin-top:.75rem} .legacy-content .req-box{background:var(--card);border:1px solid var(--border);border-radius:.55rem;padding:1.1rem 1.25rem;margin:1rem 0} .legacy-content .req-box h4{margin:0 0 .5rem;font-size:1rem} .legacy-content .req-box p{margin:0;font-size:.9rem;color:var(--muted)} .legacy-content .cta{display:inline-block;background:var(--brand);color:white;padding:.85rem 1.5rem;border-radius:.5rem;font-weight:600;text-decoration:none;margin-top:.5rem} .legacy-content .foot{margin-top:3rem;color:#888;font-size:.85rem;border-top:1px solid var(--border);padding-top:1.5rem} .legacy-content .breadcrumb{font-size:.8rem;color:var(--muted);margin-bottom:1rem} .legacy-content .breadcrumb a{color:var(--muted)} ",
